from pathlib import Path
import csv
import matplotlib.pyplot as plt

BASE = Path(__file__).resolve().parent
OUTPUT = BASE / "output"
VISUALS = OUTPUT / "visuals"
VISUALS.mkdir(parents=True, exist_ok=True)

# Read the profiles generated by brightline_incident.py.
with (OUTPUT / "distribution_profiles.csv").open(newline="") as file:
    profiles = {
        row["run"]: row
        for row in csv.DictReader(file)
    }

categories = ["High severity", "Standard severity"]
positions = [0, 1]
width = 0.24

series = [
    ("baseline", "Baseline", "#777777", -width),
    ("incident", "Incident", "#B83232", 0),
    ("corrected", "Corrected", "#333333", width),
]

fig, ax = plt.subplots(figsize=(10, 6))

for run, label, color, offset in series:
    counts = [
        int(profiles[run]["high_count"]),
        int(profiles[run]["standard_count"]),
    ]

    bars = ax.bar(
        [position + offset for position in positions],
        counts,
        width=width,
        label=label,
        color=color,
    )

    # Include the zero label so the missing category is explicit.
    ax.bar_label(bars, padding=5, fontsize=12)

ax.set_xticks(positions)
ax.set_xticklabels(categories, fontsize=13)
ax.set_ylabel("Number of closed claims")
ax.set_title(
    "Severity Distribution Before, During, and After the Incident",
    fontsize=16,
    pad=20,
)

ax.set_ylim(0, 800)
ax.set_axisbelow(True)
ax.grid(axis="y", alpha=0.2)
ax.spines[["top", "right"]].set_visible(False)
ax.legend(frameon=False, loc="upper right")

ax.annotate(
    "All 380 high-severity claims\nwere missing during the incident",
    xy=(0, 0),
    xytext=(0, 190),
    ha="center",
    fontsize=11,
    color="#D41616",
    arrowprops={
        "arrowstyle": "->",
        "color": "#B83232",
    },
)

fig.text(
    0.5, 0.025,
    "Synthetic incident data | Same frozen input; corrected policy-key mapping",
    ha="center",
    fontsize=10,
    color="#666666",
)

fig.tight_layout(rect=[0, 0.06, 1, 1])

image_path = VISUALS / "05_severity_comparison.png"
fig.savefig(image_path, dpi=300, bbox_inches="tight")

print(f"Chart saved to: {image_path}")
plt.show()